const (
	WaitEvSkip WaitEv = "skip"
)

// Wait: `wait`, shell to frame. The host chose SKIP TURN for `who`: apply the
// game's rule for passing a turn.
type Wait struct {
	// Version.
	V int `json:"v"`
	// TypeWait.
	T   string   `json:"t"`
	Ev  WaitEv   `json:"ev"`
	Who MemberID `json:"who"`
}

// Paused: `paused`, shell to frame. With `wait.pause` on: stop or resume the
// game's clock and input.
type Paused struct {
	// Version.
	V int `json:"v"`
	// TypePaused.
	T  string `json:"t"`
	On bool   `json:"on"`
}

// Sealed: `sealed`, shell to frame. A sealed message, decrypted.
type Sealed struct {
	// Version.
	V int `json:"v"`
	// TypeSealed.
	T  string  `json:"t"`
	Ch Channel `json:"ch"`
	// May carry ArrayBuffers (see Json).
	D    JSON     `json:"d"`
	From MemberID `json:"from"`
	// Set when the host sealed a message to a bot it plays: the bot it was for.
	To *MemberID `json:"to,omitempty"`
}

// Act: `act`, frame to shell. Layer 2 (manifest `state: "managed"`): this
// player's move. The platform applies it on the host with the rules' `apply({
// action, by })`; a refusal comes back as `rejected`.
type Act struct {
	// Version.
	V int `json:"v"`
	// TypeAct.
	T string `json:"t"`
	// May carry ArrayBuffers (see Json).
	A JSON `json:"a"`
}

// Input: `input`, frame to shell. Layer 2, a ticking game (manifest `tick`):
// this player's latest input. The host keeps the latest per seat and hands them
// all to `tick({ inputs, dt })`.
type Input struct {
	// Version.
	V int `json:"v"`
	// TypeInput.
	T string `json:"t"`
	// May carry ArrayBuffers (see Json).
	I JSON `json:"i"`
}

// RulesCallFn: Values of RulesCallFn.
type RulesCallFn string

// RulesCallFn values.
const (
	RulesCallFnInit     RulesCallFn = "init"
	RulesCallFnApply    RulesCallFn = "apply"
	RulesCallFnTick     RulesCallFn = "tick"
	RulesCallFnView     RulesCallFn = "view"
	RulesCallFnTurn     RulesCallFn = "turn"
	RulesCallFnBot      RulesCallFn = "bot"
	RulesCallFnResult   RulesCallFn = "result"
	RulesCallFnSnapshot RulesCallFn = "snapshot"
	RulesCallFnRestore  RulesCallFn = "restore"
	RulesCallFnSkip     RulesCallFn = "skip"
	RulesCallFnLeave    RulesCallFn = "leave"
)

// RulesCallSeatsItem
type RulesCallSeatsItem struct {
	ID   MemberID `json:"id"`
	Name string   `json:"name"`
	Team *string  `json:"team,omitempty"`
	Bot  bool     `json:"bot"`
}

// RulesCall: One call into a managed game's rules. `fn` names the rule; the
// other fields are its arguments.
type RulesCall struct {
	Fn RulesCallFn `json:"fn"`
	// init: the seated players, in party order.
	Seats []RulesCallSeatsItem `json:"seats,omitempty"`
	// init: the game's options (manifest `opts`). May carry ArrayBuffers (see
	// Json).
	Opts map[string]json.RawMessage `json:"opts,omitempty"`
	// init: a random seed.
	Seed *int `json:"seed,omitempty"`
	// init: which match of this run (0, then 1 on the first rematch…).
	Match *int `json:"match,omitempty"`
	// apply: the move. May carry ArrayBuffers (see Json).
	Action JSON `json:"action,omitempty"`
	// apply: who made it (a bot's id for a bot).
	By *MemberID `json:"by,omitempty"`
	// tick: each seat's latest input. May carry ArrayBuffers (see Json).
	Inputs map[string]JSON `json:"inputs,omitempty"`
	// tick: seconds since the last tick (1 / manifest tick).
	Dt *float64 `json:"dt,omitempty"`
	// view (null: a spectator), bot, skip, leave: the seat.
	Seat *MemberID `json:"seat,omitempty"`
	// restore: what `snapshot()` returned on the old host. May carry ArrayBuffers
	// (see Json).
	Snapshot JSON `json:"snapshot,omitempty"`
}

// RulesOut: One call's outcome: `v`, what the rule returned (apply: null or
// true when allowed, else the reason as a string; skip / leave: true if the
// game acted on it; both optional), or `err` when it threw or does not exist.
type RulesOut struct {
	// May carry ArrayBuffers (see Json).
	V   JSON    `json:"v,omitempty"`
	Err *string `json:"err,omitempty"`
}

// Rules: `rules`, shell to frame. Request, Layer 2: call a managed game's
// rules, in order, in one round trip. Reply `{ out: [rulesOut…] }`, one per
// call. Only the host's rules are live; every phone's frame answers on a
// takeover.
type Rules struct {
	// Version.
	V int `json:"v"`
	// TypeRules.
	T  string `json:"t"`
	ID ID     `json:"id"`
	// At least 1 items.
	Calls []RulesCall `json:"calls"`
}

// View: `view`, shell to frame. Layer 2: what this phone's player may see now
// (the rules' `view({ seat })`), in `state`. Sent only when it changed.
type View struct {
	// Version.
	V int `json:"v"`
	// TypeView.
	T string `json:"t"`
	// May carry ArrayBuffers (see Json).
	State JSON `json:"state"`
}

// Rejected: `rejected`, shell to frame. Layer 2: the host's rules refused this
// player's `act`.
type Rejected struct {
	// Version.
	V int `json:"v"`
	// TypeRejected.
	T string `json:"t"`
	// May carry ArrayBuffers (see Json).
	A      JSON   `json:"a,omitempty"`
	Reason string `json:"reason"`
}

// RuntimeFile: `runtime.file`, frame to shell. Request: a file of a runtime the
// platform ships, for a game whose language needs one (manifest `runtime:
// "python"`: Pyodide, from sdk/v1/pyodide/). Reply `{ bytes, type }`. Only that
// folder; it does not count toward the game's size cap.
type RuntimeFile struct {
	// Version.
	V int `json:"v"`
	// TypeRuntimeFile.
	T  string `json:"t"`
	ID ID     `json:"id"`
	// Relative to the runtime's folder, e.g. `pyodide.asm.wasm`. At most 256
	// chars.
	Path string `json:"path"`
}

// Envelope is what every message shares: decode it to see what a message is.
type Envelope struct {
	V int    `json:"v"`
	T string `json:"t"`
}

// ErrUnknownType wraps a t this version does not know. The protocol says to
// ignore such a message: the other side may be newer.
var ErrUnknownType = errors.New("arcade: unknown message type")

// DecodeToShell reads a frame-to-shell message into a pointer to its struct (*Hello, ...).
func DecodeToShell(b []byte) (any, error) {
	var e Envelope
	if err := json.Unmarshal(b, &e); err != nil {
		return nil, err
	}
	if e.V != Version {
		return nil, fmt.Errorf("arcade: message v %d, want %d", e.V, Version)
	}
	var m any
	switch e.T {
	case TypeHello:
		m = &Hello{}
	case TypeReady:
		m = &Ready{}
	case TypeReply:
		m = &Reply{}
	case TypeListen:
		m = &Listen{}
	case TypeSend:
		m = &Send{}
	case TypeEmitAs:
		m = &EmitAs{}
	case TypeMeta:
		m = &Meta{}
	case TypeStoreSet:
		m = &StoreSet{}
	case TypeSessionSet:
		m = &SessionSet{}
	case TypeAsset:
		m = &Asset{}
	case TypeResult:
		m = &Result{}
	case TypeEnd:
		m = &End{}
	case TypeHostNew:
		m = &HostNew{}
	case TypeToast:
		m = &Toast{}
	case TypeAsk:
		m = &Ask{}
	case TypeHaptic:
		m = &Haptic{}
	case TypeTimerOpen:
		m = &TimerOpen{}
	case TypeTimerDo:
		m = &TimerDo{}
	case TypeWaitTurn:
		m = &WaitTurn{}
	case TypeWaitPause:
		m = &WaitPause{}
	case TypeSealListen:
		m = &SealListen{}
	case TypeSealSend:
		m = &SealSend{}
	case TypeCommit:
		m = &Commit{}
	case TypeVerify:
		m = &Verify{}
	case TypeAct:
		m = &Act{}
	case TypeInput:
		m = &Input{}
	case TypeRuntimeFile:
		m = &RuntimeFile{}
	default:
		return nil, fmt.Errorf("%w: %q", ErrUnknownType, e.T)
	}
	if err := json.Unmarshal(b, m); err != nil {
		return nil, err
	}
	return m, nil
}

// DecodeToFrame reads a shell-to-frame message into a pointer to its struct (*Init, ...).
func DecodeToFrame(b []byte) (any, error) {
	var e Envelope
	if err := json.Unmarshal(b, &e); err != nil {
		return nil, err
	}
	if e.V != Version {
		return nil, fmt.Errorf("arcade: message v %d, want %d", e.V, Version)
	}
	var m any
	switch e.T {
	case TypeInit:
		m = &Init{}
	case TypeRoster:
		m = &Roster{}
	case TypeJoin:
		m = &Join{}
	case TypeLeave:
		m = &Leave{}
	case TypeMsg:
		m = &Msg{}
	case TypeThemeSet:
		m = &ThemeSet{}
	case TypeTakeOver:
		m = &TakeOver{}
	case TypeUnmount:
		m = &Unmount{}
	case TypeReply:
		m = &Reply{}
	case TypeTimer:
		m = &Timer{}
	case TypeWait:
		m = &Wait{}
	case TypePaused:
		m = &Paused{}
	case TypeSealed:
		m = &Sealed{}
	case TypeRules:
		m = &Rules{}
	case TypeView:
		m = &View{}
	case TypeRejected:
		m = &Rejected{}
	default:
		return nil, fmt.Errorf("%w: %q", ErrUnknownType, e.T)
	}
	if err := json.Unmarshal(b, m); err != nil {
		return nil, err
	}
	return m, nil
}
